package me.milstead.banking.entity;

import jakarta.annotation.Nullable;
import jakarta.persistence.*;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import lombok.*;

import java.util.UUID;

/**
 * Represents a customer savings account in the database and domain services.
 */
@Getter
@Setter
@Entity
@AllArgsConstructor
@NoArgsConstructor
@Builder
@ToString
// Don't use @Data we want to write our own JPA compatible equals and hashCode.
public class SavingsAccount {

    /**
     * Autogenerated.
     */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    /**
     * Account number.
     * UUID wouldn't be my first choice for prod system because of b-tree performance,
     * but the requirements essentially specified two IDs.
     */
    @Column(nullable = false, unique = true)
    @Builder.Default
    private UUID accountNumber = UUID.randomUUID();

    /**
     * Customer name - would have been better to use an ID here.
     * Mandatory.
     */
    @Column(nullable = false, unique = true)
    @NotNull
    private String customerName;

    /**
     * Optional 5 to 30 characters.
     */
    @Column(nullable = true, length = 30)
    @Size(min = 5, max = 30)
    @Nullable
    private String nickname;

}
